PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT DISTINCT ?point ?tsid ?unit ?class WHERE {
  ?point rdf:type brick:ElectricPower .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point rdf:type ?class }
  OPTIONAL { ?point brick:hasSubParameter ?unit }
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT DISTINCT ?point ?tsid WHERE {
  ?point rdf:type brick:ElectricEnergy .
  ?point ref:hasTimeseriesId ?tsid .
}
